DROP TABLE IF EXISTS nv_backups;

CREATE TABLE `nv_backups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `date_created` int(11) NOT NULL,
  `size` int(11) NOT NULL,
  `status` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `runtime` int(11) NOT NULL,
  `version` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_block_groups;

CREATE TABLE `nv_block_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `code` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `blocks` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_blocks;

CREATE TABLE `nv_blocks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_published` int(11) NOT NULL,
  `date_unpublish` int(11) NOT NULL,
  `position` int(11) NOT NULL,
  `fixed` tinyint(1) NOT NULL,
  `categories` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `exclusions` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `elements` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `access` tinyint(1) NOT NULL,
  `groups` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  `trigger` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_modified` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_brands;

CREATE TABLE `nv_brands` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` int(11) NOT NULL,
  `url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_comments;

CREATE TABLE `nv_comments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `object_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'item',
  `object_id` int(11) NOT NULL,
  `user` int(11) NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ip` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_created` int(11) NOT NULL,
  `date_modified` int(11) NOT NULL,
  `last_modified_by` int(11) NOT NULL,
  `reply_to` int(11) NOT NULL DEFAULT '0',
  `subscribed` tinyint(1) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL,
  `message` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `item` (`object_id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_countries;

CREATE TABLE `nv_countries` (
  `id` int(32) NOT NULL AUTO_INCREMENT,
  `country_code` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `alpha3` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `numeric` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `continent` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lang` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `country_code` (`country_code`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_countries_regions;

CREATE TABLE `nv_countries_regions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `numeric` int(11) NOT NULL DEFAULT '0',
  `country` int(11) NOT NULL,
  `abbreviation` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lang` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_coupons;

CREATE TABLE `nv_coupons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_begin` int(11) NOT NULL,
  `date_end` int(11) NOT NULL,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `minimum_spend` decimal(12,4) NOT NULL,
  `times_allowed_customer` int(11) NOT NULL,
  `times_allowed_globally` int(11) NOT NULL,
  `discount_value` decimal(12,4) NOT NULL,
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_extensions;

CREATE TABLE `nv_extensions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `extension` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  `settings` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_feeds;

CREATE TABLE `nv_feeds` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `categories` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `format` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` int(11) NOT NULL,
  `entries` int(4) NOT NULL,
  `content` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `views` int(11) NOT NULL,
  `permission` int(1) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_files;

CREATE TABLE `nv_files` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'folder,image,video,audio,document',
  `parent` int(11) NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `size` int(11) NOT NULL,
  `mime` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `width` int(11) NOT NULL,
  `height` int(11) NOT NULL,
  `focalpoint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_added` int(11) NOT NULL,
  `uploaded_by` int(11) NOT NULL,
  `access` tinyint(1) NOT NULL,
  `groups` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `permission` tinyint(4) NOT NULL,
  `system` tinyint(1) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_functions;

CREATE TABLE `nv_functions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `codename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lid` int(11) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_items;

CREATE TABLE `nv_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `association` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` int(11) NOT NULL,
  `embedding` tinyint(1) NOT NULL,
  `template` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_to_display` int(11) NOT NULL,
  `date_published` int(11) NOT NULL,
  `date_unpublish` int(11) NOT NULL,
  `date_created` int(32) NOT NULL,
  `date_modified` int(32) NOT NULL,
  `author` int(11) NOT NULL,
  `galleries` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `comments_enabled_to` int(11) NOT NULL,
  `comments_moderator` int(11) NOT NULL,
  `access` tinyint(1) NOT NULL,
  `groups` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `permission` tinyint(4) NOT NULL,
  `views` int(11) NOT NULL,
  `votes` int(11) NOT NULL,
  `score` int(2) NOT NULL,
  `position` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_languages;

CREATE TABLE `nv_languages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL,
  `english_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nv_dictionary` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_menus;

CREATE TABLE `nv_menus` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `codename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lid` int(11) NOT NULL COMMENT 'Dictionary label ID',
  `notes` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `functions` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enabled` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_notes;

CREATE TABLE `nv_notes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `user` int(11) NOT NULL,
  `item_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_id` int(11) NOT NULL,
  `background` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_created` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_orders;

CREATE TABLE `nv_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `webuser` int(11) NOT NULL,
  `reference` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_created` int(11) NOT NULL,
  `date_updated` int(11) NOT NULL,
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_data` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_notes` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtotal_amount` decimal(24,2) NOT NULL,
  `subtotal_taxes_cost` decimal(24,2) NOT NULL,
  `subtotal_invoiced` decimal(24,2) NOT NULL,
  `shipping_method` int(11) NOT NULL,
  `shipping_amount` decimal(12,2) NOT NULL,
  `shipping_tax` decimal(12,2) NOT NULL,
  `shipping_invoiced` decimal(12,2) NOT NULL,
  `shipping_data` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipping_address` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `billing_address` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `coupon` int(11) NOT NULL,
  `coupon_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_amount` decimal(8,2) NOT NULL,
  `discount_percentage` decimal(4,2) NOT NULL,
  `discount_invoiced` decimal(8,2) NOT NULL,
  `total` decimal(24,2) NOT NULL,
  `payment_done` tinyint(1) NOT NULL,
  `payment_method` int(11) NOT NULL,
  `payment_data` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `history` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_orders_lines;

CREATE TABLE `nv_orders_lines` (
  `id` int(11) NOT NULL,
  `website` int(11) NOT NULL,
  `order` int(11) NOT NULL,
  `position` int(11) NOT NULL,
  `customer` int(11) NOT NULL,
  `product` int(11) NOT NULL,
  `sku` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `option` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(8,2) NOT NULL,
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_price` decimal(20,2) NOT NULL,
  `base_price` decimal(20,2) NOT NULL,
  `tax_value` decimal(4,2) NOT NULL,
  `tax_amount` decimal(20,2) NOT NULL,
  `total` decimal(20,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_paths;

CREATE TABLE `nv_paths` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `object_id` int(11) NOT NULL,
  `lang` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `views` bigint(32) NOT NULL DEFAULT '0',
  `cache_file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cache_expires` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `object_id` (`object_id`),
  KEY `path` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_permissions;

CREATE TABLE `nv_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `function` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `profile` int(11) NOT NULL,
  `user` int(11) NOT NULL,
  `value` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `website` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_products;

CREATE TABLE `nv_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `category` int(11) NOT NULL,
  `type` int(11) NOT NULL,
  `template` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_to_display` int(11) NOT NULL,
  `date_published` int(11) NOT NULL,
  `date_unpublish` int(11) NOT NULL,
  `date_created` int(32) NOT NULL,
  `date_modified` int(32) NOT NULL,
  `author` int(11) NOT NULL,
  `brand` int(11) NOT NULL,
  `sku` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `barcode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_price` decimal(20,2) NOT NULL,
  `base_price_currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tax_class` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tax_value` decimal(4,2) NOT NULL,
  `cost` decimal(20,2) NOT NULL,
  `cost_currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `offer_price` decimal(20,2) NOT NULL,
  `offer_begin_date` int(11) NOT NULL,
  `offer_end_date` int(11) NOT NULL,
  `width` decimal(10,2) NOT NULL,
  `height` decimal(10,2) NOT NULL,
  `depth` decimal(10,2) NOT NULL,
  `size_unit` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `weight` decimal(10,2) NOT NULL,
  `weight_unit` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL,
  `inventory` tinyint(1) NOT NULL,
  `stock_available` int(11) NOT NULL,
  `options` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `galleries` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `comments_enabled_to` int(11) NOT NULL,
  `comments_moderator` int(11) NOT NULL,
  `access` tinyint(1) NOT NULL,
  `groups` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `permission` tinyint(4) NOT NULL,
  `views` int(11) NOT NULL,
  `votes` int(11) NOT NULL,
  `score` int(2) NOT NULL,
  `position` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_profiles;

CREATE TABLE `nv_profiles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `menus` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_properties;

CREATE TABLE `nv_properties` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `template` int(11) NOT NULL,
  `element` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `options` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `dvalue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `multilanguage` set('false','true') COLLATE utf8mb4_unicode_ci NOT NULL,
  `helper` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` int(11) NOT NULL,
  `enabled` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_properties_items;

CREATE TABLE `nv_properties_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `property_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `element` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `node_id` int(11) NOT NULL,
  `node_uid` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `property_id` (`property_id`),
  KEY `property_id_2` (`property_id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_search_log;

CREATE TABLE `nv_search_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `date` int(11) NOT NULL,
  `webuser` int(11) NOT NULL,
  `origin` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `request` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_settings;

CREATE TABLE `nv_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user` int(11) NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_shipping_methods;

CREATE TABLE `nv_shipping_methods` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `codename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` int(11) NOT NULL,
  `permission` int(11) NOT NULL,
  `rates` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_structure;

CREATE TABLE `nv_structure` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
  `parent` int(11) NOT NULL,
  `position` int(8) NOT NULL,
  `access` tinyint(1) NOT NULL,
  `groups` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `permission` tinyint(1) NOT NULL,
  `icon` int(11) NOT NULL,
  `metatags` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `template` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_published` int(11) NOT NULL,
  `date_unpublish` int(11) NOT NULL,
  `views` int(11) NOT NULL,
  `votes` int(11) NOT NULL,
  `score` int(2) NOT NULL,
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS nv_templates;

CREATE TABLE `nv_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `website` int(11) NOT NULL,
